<script setup>
import { onMounted, ref } from 'vue';import { useRoute } from 'vue-router';import { Trophy, Users, Wallet, Star } from '@lucide/vue'
import { api } from '../../services/api';import { money, number, positionName, date } from '../../utils'
import LoadingBlock from '../../components/LoadingBlock.vue';import EntityAvatar from '../../components/EntityAvatar.vue';import RankMovement from '../../components/RankMovement.vue';import HonourMedals from '../../components/HonourMedals.vue';import EmptyState from '../../components/EmptyState.vue'
const route=useRoute(),loading=ref(true),data=ref(null)
onMounted(async()=>{try{data.value=(await api.get(`/public/clubs/${route.params.id}`,null,{auth:false})).data}finally{loading.value=false}})
</script>
<template><div class="container page"><LoadingBlock v-if="loading"/><template v-else-if="data"><section class="club-hero glass"><EntityAvatar :src="data.club.logo_url" :name="data.club.name" :size="104"/><div class="club-heading"><span class="eyebrow">{{ data.club.code }}</span><h1>{{ data.club.name }}</h1><p>{{ data.club.short_name }}</p></div><div class="club-world-rank"><small>Hạng thế giới</small><b>#{{ data.club.rank_position||'—' }}</b><RankMovement :change="data.club.rank_change" :previous="data.club.previous_rank"/></div></section><div class="grid-4 metrics"><article class="glass stat-card"><Users :size="19" class="text-primary"/><div class="stat-value">{{ data.players.length }}</div><div class="stat-label">Cầu thủ đội một</div></article><article class="glass stat-card"><Wallet :size="19" class="text-green"/><div class="stat-value">{{ money(data.club.balance,true) }}</div><div class="stat-label">Số dư CLB</div></article><article class="glass stat-card"><Trophy :size="19" class="text-yellow"/><div class="stat-value">{{ data.achievements.length }}</div><div class="stat-label">Danh hiệu lịch sử</div></article><article class="glass stat-card"><Star :size="19" class="text-primary"/><div class="stat-value">{{ number(data.club.score) }}</div><div class="stat-label">Điểm xếp hạng</div></article></div><section class="glass honour-strip"><div><span class="eyebrow">Bảng vàng lịch sử</span><h3>Huy chương và cột mốc</h3></div><HonourMedals :gold="data.honourSummary?.gold_count" :silver="data.honourSummary?.silver_count" :bronze="data.honourSummary?.bronze_count" :quarterfinal="data.honourSummary?.quarterfinal_count"/><div class="honour-points"><b>{{ number(data.honourSummary?.honour_points) }}</b><span>Điểm thành tích</span></div></section><div class="detail-grid"><section class="glass card"><div class="section-title"><div><span class="eyebrow">Đội hình</span><h2>Cầu thủ</h2></div></div><EmptyState v-if="!data.players.length"/><div v-else class="table-wrap"><table><thead><tr><th>#</th><th>Cầu thủ</th><th>Vị trí</th><th>Lương/mùa</th><th>Giá trị</th></tr></thead><tbody><tr v-for="p in data.players" :key="p.id"><td><b>{{ p.shirt_number||'—' }}</b></td><td><RouterLink :to="`/players/${p.id}`" class="entity"><EntityAvatar :src="p.photo_url" :name="p.full_name" :size="34" round/><span class="entity-name">{{ p.full_name }}</span></RouterLink></td><td>{{ positionName(p.position) }}</td><td>{{ money(p.salary_per_season,true) }}</td><td><b>{{ money(p.market_value,true) }}</b></td></tr></tbody></table></div></section><section class="glass card"><div class="section-title"><div><span class="eyebrow">Phòng truyền thống</span><h2>Danh hiệu</h2></div></div><EmptyState v-if="!data.achievements.length"/><div v-else class="award-list"><article v-for="a in data.achievements" :key="a.id"><div class="medal">{{ a.medal_type==='GOLD'?'🥇':a.medal_type==='SILVER'?'🥈':a.medal_type==='BRONZE'?'🥉':'⚔️' }}</div><div><b>{{ a.achievement_name }}</b><p>{{ a.competition_name }} · {{ a.season_name }} · {{ date(a.awarded_at) }}</p></div></article></div></section></div></template></div></template>
<style scoped>.club-hero{padding:28px;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:24px;position:relative;overflow:hidden}.club-hero:after{content:'';position:absolute;right:-70px;width:300px;height:300px;border-radius:50%;background:radial-gradient(circle,rgba(57,130,255,.18),transparent 70%)}.club-heading h1{font-size:clamp(29px,4vw,48px);margin:6px 0}.club-world-rank{text-align:right;position:relative;z-index:1}.club-world-rank small{display:block;color:var(--muted)}.club-world-rank b{display:block;font:800 44px Manrope;margin:5px 0;color:var(--yellow)}.metrics{margin:20px 0}.honour-strip{padding:16px 18px;margin:-8px 0 20px;display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:18px}.honour-strip h3{margin-top:4px}.honour-points{text-align:right}.honour-points b,.honour-points span{display:block}.honour-points b{font:800 25px Manrope;color:var(--yellow)}.honour-points span{font-size:9px;color:var(--muted)}.detail-grid{display:grid;grid-template-columns:1.35fr .65fr;gap:20px}.award-list{display:grid;gap:10px}.award-list article{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--line);border-radius:12px}.medal{font-size:28px}.award-list b{font-size:14px}.award-list p{font-size:11px}@media(max-width:900px){.detail-grid{grid-template-columns:1fr}}@media(max-width:620px){.honour-strip{grid-template-columns:1fr}.honour-points{text-align:left}.club-hero{grid-template-columns:auto 1fr}.club-world-rank{grid-column:1/-1;text-align:left;display:flex;align-items:center;gap:12px}.club-world-rank b{font-size:32px}}</style>
